    image_patch = ImagePatch(image)
    sticks = image_patch.find("sticks")
    if len(sticks) < 2:
        return image_patch

    sticks.sort(key=lambda s: s.compute_depth())
    closest_two_sticks = sticks[:2]

    veggies = image_patch.find("veggies")
    if not veggies:
        return image_patch

    min_distance = float('inf')
    best_vegetable = None

    for veggie in veggies:
        for stick in closest_two_sticks:
            dist = distance(stick, veggie)
            if dist < min_distance:
                min_distance = dist
                best_vegetable = veggie

    return best_vegetable

