def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    carrots = image_patch.find("carrot")
    peppers = image_patch.find("red pepper")

    if not carrots or not peppers:
        return image_patch

    closest_pepper = min(peppers, key=lambda p: p.compute_depth())
    foreground_carrots = [c for c in carrots if is_in_front_of(c, closest_pepper)]

    if not foreground_carrots:
        return image_patch

    return min(foreground_carrots, key=lambda c: c.compute_depth())

